 const operate=(id:string,action:string,value?:boolean)=>{setStates({...stateRef.current});setCircuit(c=>{const n=clone(c),item=n.components.find(x=>x.id===id);if(!item)return c;if(action==='press')item.state.pressed=!!value;if(action==='toggle'&&!item.state.tripped)item.state.closed=!item.state.closed;if(action==='trip')item.state.tripped=!item.state.tripped;if(action==='reset'){item.state.tripped=false;item.state.closed=false;}return n;});if(action!=='press'||value)record(`${circuit.components.find(c=>c.id===id)?.instanceName}: ${action}${action==='press'?(value?' DOWN':' UP'):''}`);};
