 const addComponent=(definitionId:string,x?:number,y?:number)=>{const d=getDef(definitionId);let id='';edit(c=>{const number=1+c.components.filter(n=>getDef(n.definitionId).prefix===d.prefix).length;id=crypto.randomUUID();let px=x,py=y;const rails=c.components.filter(n=>n.definitionId==='dinrail');if(px===undefined||py===undefined){if(definitionId!=='dinrail'&&rails.length){const rail=rails[0],items=c.components.filter(n=>n.definitionId!=='dinrail'&&Math.abs(n.y-(rail.y-118))<100),slot=items.length;px=rail.x+24+(slot%2)*230;py=rail.y-118+Math.floor(slot/2)*180;}else{let slot=0;while(c.components.some(n=>Math.abs(n.x-(180+(slot%4)*230))<185&&Math.abs(n.y-(140+Math.floor(slot/4)*190))<145))slot++;px=180+(slot%4)*230;py=140+Math.floor(slot/4)*190;}}let gx=Math.round(px/20)*20,gy=Math.round(py/20)*20;const overlaps=(ax:number,ay:number)=>c.components.some(n=>ax< n.x+componentWidth(n)-24&&ax+componentWidth({definitionId})-24>n.x&&ay<n.y+componentHeight(getDef(n.definitionId))-20&&ay+componentHeight(d)-20>n.y);if(overlaps(gx,gy)){let slot=0;while(slot<200){const tx=180+(slot%6)*210,ty=140+Math.floor(slot/6)*155;if(!overlaps(tx,ty)){gx=tx;gy=ty;break;}slot++;}}c.components.push(component(id,definitionId,gx,gy,d.prefix+number));});if(id){setSelected([id]);if(d.model==='unsupported')msg(`${d.name}: ${language==='id'?'tersedia untuk tata letak, model simulasi belum tersedia.':'layout reference only; no simulation model is available.'}`);}};
