 const terminalClick=(e:React.MouseEvent,end:Endpoint)=>{e.stopPropagation();if(running){if(bottom==='Multimeter'){if(!red||black){setRed(key(end));setBlack('');}else{setBlack(key(end));setMeasurements(n=>n+1);}}else{setSelected([end.componentId]);setBottom('Multimeter');setRed(key(end));setBlack('');}return;}if(tool!=='wire'){setTool('wire');setPending(end);return;}if(!pending){setPending(end);return;}if(key(pending)===key(end)){setPending(null);return;}edit(c=>{if(c.wires.some(w=>[key(w.from),key(w.to)].sort().join() ===[key(pending),key(end)].sort().join()))return;c.wires.push({id:crypto.randomUUID(),from:pending,to:end,properties:{color:pending.terminalId==='−'||pending.terminalId==='N'?'#428cd3':'#df6960',conductorSize:1.5}});});setPending(null);};
 const terminalWorldPoint=(e:Endpoint,edge=false)=>{const c=circuit.components.find(n=>n.id===e.componentId);if(!c)return {x:0,y:0};const d=getDef(c.definitionId),h=componentHeight(d),p=terminalPosition(d,d.terminals.indexOf(e.terminalId),viewMode,h);if(edge&&viewMode!=='schematic'&&p.x>10&&p.x<138){const x=viewMode==='panel'?18:30,w=viewMode==='panel'?112:88,sy=(viewMode==='panel'?Math.max(h-30,76):h-66)/120,bounds=[{v:p.x-(x+12*w/100),axis:'x' as const,value:x+12*w/100},{v:x+89*w/100-p.x,axis:'x' as const,value:x+89*w/100},{v:p.y-(27+9*sy),axis:'y' as const,value:27+9*sy},{v:27+116*sy-p.y,axis:'y' as const,value:27+116*sy}],side=bounds.reduce((a,b)=>a.v<b.v?a:b);if(side.axis==='x')p.x=side.value;else p.y=side.value;}const rad=c.rotation*Math.PI/180,cx=componentWidth(c)/2,cy=h/2;return {x:c.x+cx+(p.x-cx)*Math.cos(rad)-(p.y-cy)*Math.sin(rad),y:c.y+cy+(p.x-cx)*Math.sin(rad)+(p.y-cy)*Math.cos(rad)};};
