 const beginDrag=(e:React.PointerEvent,id?:string)=>{if(tool==='pan')id=undefined;if(tool==='wire'||running&&id)return;e.stopPropagation();svg.current?.setPointerCapture(e.pointerId);const p=point(e);drag.current={id,startX:p.x,startY:p.y,x:id?circuit.components.find(n=>n.id===id)!.x:pan.x,y:id?circuit.components.find(n=>n.id===id)!.y:pan.y,before:clone(circuit)};if(id){setSelected(e.shiftKey?[...new Set([...selected,id])]:selected.includes(id)?selected:[id]);setSelectedWire(null);}else if(tool!=='pan')setSelected([]);};
