 const paste=()=>{if(!copyRef.current.length)return;edit(c=>{const ids=new Map<string,string>();for(const n of copyRef.current){const id=crypto.randomUUID();ids.set(n.id,id);c.components.push({...clone(n),id,instanceName:n.instanceName+' copy',x:n.x+40,y:n.y+40});}for(const w of circuit.wires)if(ids.has(w.from.componentId)&&ids.has(w.to.componentId))c.wires.push({...clone(w),id:crypto.randomUUID(),from:{...w.from,componentId:ids.get(w.from.componentId)!},to:{...w.to,componentId:ids.get(w.to.componentId)!}});});};
 useEffect(()=>{const handle=(e:KeyboardEvent)=>{if(e.key==='Escape'){setMenu(false);setPending(null);setTool('select');setSelected([]);}if((e.target as HTMLElement).matches('input,textarea,select'))return;if(tab!=='Simulator')return;if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove();}if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();e.shiftKey?redo():undo();}if((e.ctrlKey||e.metaKey)&&e.key==='c'){e.preventDefault();copyRef.current=circuit.components.filter(c=>selected.includes(c.id));msg('Komponen disalin. Ctrl+V untuk paste.');}if((e.ctrlKey||e.metaKey)&&e.key==='v'){e.preventDefault();paste();}};window.addEventListener('keydown',handle);return()=>window.removeEventListener('keydown',handle);});
 const run=()=>{setPending(null);setStates({...stateRef.current});setRunning(true);record('RUN · graph evaluation');setBottom('Validation');};
