 const importCircuit=async(e:React.ChangeEvent<HTMLInputElement>)=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>8000000)throw Error('File maksimum 8 MB.');const parsed=CircuitSchema.safeParse(JSON.parse(await f.text()));if(!parsed.success)throw Error('Format circuit JSON atau terminal tidak valid.');const c={...parsed.data,id:crypto.randomUUID()};setRunning(false);setStates({});setCircuit(c);setHistory([]);setFuture([]);setPending(null);setSelected([]);setSelectedWire(null);setTab('Simulator');setTimeout(()=>fit(c),70);msg('Rangkaian berhasil diimpor.');}catch(err){msg((err as Error).message);}e.target.value='';};
