 const startChallenge=(id:string)=>{const ch=challenges.find(x=>x.id===id)!;const c=template(ch.template);c.name='Challenge · '+ch.name;if(id==='return')c.wires=c.wires.filter(w=>!(w.from.componentId==='h'&&w.from.terminalId==='−'));if(id==='coil')c.components.find(c=>c.id==='k')!.properties.voltage=230;if(id==='phase')c.wires=c.wires.filter(w=>!(w.from.componentId==='ol'&&w.from.terminalId==='T3'));setCircuit(c);setStates({});setRunning(false);setChallenge(id);setChallengeTime(0);setChanges(0);setHints(0);setMeasurements(0);setShowHint(false);setHistory([]);setFuture([]);setPending(null);go('Simulator');setTimeout(()=>fit(c),70);};
